def parse_headers(s):
    headers = {}
    for item in s.split(';'):
        key, value = item.split(':', 1)
        key = key.strip()
        if key:
            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1]
            value = value.strip()
            headers[key] = value
    return headers
```

