def unflatten(flat):
    def parse_key(key):
        if '[' in key:
            k, i = key.split('[')
            i = int(i[:-1])
            return k, i
        elif '.' in key:
            k, rest = key.split('.')
            return k, rest
        else:
            return key, None

    nested = {}
    for key, value in flat.items():
        k, index = parse_key(key)
        current = nested
        while '.' in k:
            k, rest = k.split('.', 1)
            current.setdefault(k, {})
            current = current[k]
        if index is not None:
            current.setdefault(k, [None] * (index + 1))
            current[k][index] = value
        else:
            current[k] = value
    return nested
```

