def parse_duration(s):
    if not s:
        return None
    try:
        parts = s.lower().split('h')
        hours = int(parts[0]) * 3600 if parts[0] else 0
        minutes = int(parts[1].split('m')[0]) * 60 if 'm' in s else 0
        seconds = int(parts[1].split('m')[1]) if 'm' in s and len(parts) > 1 else 0
        return hours + minutes + seconds
    except:
        return None
